function furniturePose(item){return item.kind==='bed'?'lie-rest':item.kind==='bath'?'bathe':'chair-sit';}
function furnitureExit(item){return item.kind==='bed'?'起床':item.kind==='bath'?'离开浴池':'站起来';}
function furnitureStatus(item){return chinaRoyalPlayerMeal?.statusLabel(item.id)|| (item.kind==='bed'?'躺在寝具上休息':item.kind==='bath'?(item.bathPose?'坐在温泉中休息':'穿浴衣坐在水中泡澡'):'安静坐一会儿');}
function furnitureAction(item){return item.action;}
function stationIntent(station){if(chinaClinic?.borrowed(station?.id))return null;return playerStationIntent(station,{clinicCollection:chinaClinic?.collectionIntent()});}
